INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('77fca868-67b4-4f17-91cd-c74cb2546161', 'c1c2c3d4-3030-4000-8000-000000000030', 4, 'Nomear', 'Semana 1 — Despertar', '{"pch": "Aquilo que voc\u00ea n\u00e3o nomeia\u2026 te controla.", "verse": "Gn 2,19-20", "lectio": "Assim como Ad\u00e3o nomeou cada criatura, nomeie o que vive dentro de voc\u00ea.", "practice": "Escreva: qual medo, h\u00e1bito ou ferida eu ainda n\u00e3o nomeei?", "question": "O que voc\u00ea ainda n\u00e3o enfrentou?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;